def count_black_squares(N):
    # Assuming (1, 1) is black. Black squares are where i+j is even.
    black_count = 0
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if (i + j) % 2 == 0:
                # Check corner condition: All corners must be black.
                # (1, 1): 1+1=2 (Even -> Black)
                # (1, N): 1+N (Even if N is odd)
                # (N, 1): N+1 (Even if N is odd)
                # (N, N): N+N = 2N (Always Even -> Black)
                if N % 2 != 0:
                    if (i == 1 or i == N) and (j == 1 or j == N):
                        # Since i+j is even, the corners are naturally accounted for
                        pass
                black_count += 1
    return black_count

